mapper.update:
update qt_interview_application
apply_status = #{applyStatus}, offered_department = #{offeredDepartment}, join_status = #{joinStatus}, final_status = #{finalStatus}, notice_status = #{noticeStatus}, update_by = #{updateBy}, update_time = now(),
where application_id = #{applicationId}

mapper.select:
select e.evaluation_id, e.application_id, e.round_id, e.department, e.evaluator_user_id, e.content,
       e.create_by, e.create_time, e.update_by, e.update_time,
       u.nick_name as evaluator_name,
       u.user_name as evaluator_user_name
from qt_interview_evaluation e
left join sys_user u on e.evaluator_user_id = u.user_id

    and e.application_id = #{applicationId}
    and e.round_id = #{roundId}
    and e.department = #{department}
    and e.evaluator_user_id = #{evaluatorUserId}

order by e.create_time asc

mapper.insert:
insert into sys_user_role(user_id, role_id)
select #{userId}, #{roleId} from dual
where not exists (
    select 1 from sys_user_role
    where user_id = #{userId} and role_id = #{roleId}
)
